{
  "@context": "https://schema.org",
  "@type": "WebPage",
  "@id": "/random-4#page",
  "url": "/random-4",
  "name": "You seldom, if ever, see either pure state — Judge DiCesaro",
  "isPartOf": {
    "@id": "/#website"
  },
  "mainEntity": {
    "@type": "Quotation",
    "text": "In science, if you know what you are doing, you should not be doing it. In engineering, if you do not know what you are doing, you should not be doing it. Of course, you seldom, if ever, see either pure state.",
    "creator": {
      "@type": "Person",
      "name": "Richard Hamming"
    },
    "isBasedOn": {
      "@type": "Book",
      "name": "The Art of Doing Science and Engineering"
    }
  }
}
